  function esc(v=''){ return String(v).replace(/[&<>"']/g, m => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m])); }
  function num(v, fallback=0){ const n = Number(v); return Number.isFinite(n) ? n : fallback; }
  function attr(el, n, fallback=''){ return el ? (el.getAttribute(n) ?? fallback) : fallback; }
  function direct(root, tag){ return root ? [...root.children].find(e => e.localName === tag) || null : null; }
