  // Die HLD enthält die Grundtalente; diese drei Metatalente werden von der
  // Helden-Software für den Druckbogen daraus abgeleitet und stehen nicht als
  // aktuelle, steigerbare Talente in der normalen talentliste.
  function buildMetaTalents(talents){
    const byName=new Map(talents.map(t=>[t.name,t]));
    const val=n=>byName.get(n)?.value;
    const have=(...names)=>names.every(n=>byName.has(n));
    const capped=(raw,parts)=>Math.min(Math.round(raw),2*Math.min(...parts));
    const result=[];
    if(have('Wildnisleben','Sinnenschärfe','Pflanzenkunde')){
      const w=val('Wildnisleben'),s=val('Sinnenschärfe'),p=val('Pflanzenkunde');
      const v=capped((w+s+p)/3,[w,s,p]);
      const detail=`aus Wildnisleben ${w}, Sinnenschärfe ${s}, Pflanzenkunde ${p}`;
      result.push({name:'Nahrung sammeln',probe:' (MU/IN/FF)',value:v,se:false,method:'',be:'',k:'B',specs:[],mh:false,category:'Natur',meta:true,metaDetail:detail});
      result.push({name:'Kräuter suchen',probe:' (MU/IN/FF)',value:v,se:false,method:'',be:'',k:'B',specs:[],mh:false,category:'Natur',meta:true,metaDetail:detail});
    }
    if(have('Selbstbeherrschung','Sinnenschärfe')){
      const sb=val('Selbstbeherrschung'),ss=val('Sinnenschärfe');
      const raw=Math.floor((sb+2*ss+1)/3);
      const v=Math.min(raw,2*Math.min(sb,ss));
      result.push({name:'Wachehalten',probe:' (MU/IN/KO)',value:v,se:false,method:'',be:'',k:'B',specs:[],mh:false,category:'Natur',meta:true,metaDetail:`aus Selbstbeherrschung ${sb}, Sinnenschärfe ${ss}`});
    }
    return result;
  }

  async function openFile(file,sourceMeta={source:'local'}){
    if(!file) return;
    status('HLD wird gelesen …','ok');
    try{
      const zip = await JSZip.loadAsync(file);
      const names = Object.keys(zip.files).filter(n => /^held_.*\.xml$/i.test(n) && !zip.files[n].dir);
      if(!names.length) throw new Error('Keine held_*.xml-Dateien im Archiv gefunden.');
      const heroes=[];
      for(const fileName of names){
        const text = await zip.files[fileName].async('string');
        const doc = new DOMParser().parseFromString(text,'application/xml');
        if(doc.querySelector('parsererror')) continue;
        const held = doc.querySelector('helden > held');
        if(!held) continue;
        heroes.push({fileName,text,doc,key:attr(held,'key'),name:attr(held,'name',fileName),stand:attr(held,'stand')});
      }
      if(!heroes.length) throw new Error('Die XML-Dateien konnten nicht als Helden-Software-Helden erkannt werden.');
      heroes.sort((a,b)=>a.name.localeCompare(b.name,'de'));
      state.heroes=heroes; state.fileName=file.name; state.source=sourceMeta.source||'local'; state.cloudHld=sourceMeta.cloudHld||null;
      $('#heroSelect').innerHTML=heroes.map(h=>`<option value="${esc(h.key)}">${esc(h.name)}</option>`).join('');
      $('#fileInfo').textContent=`${file.name} · ${heroes.length} Helden · ${(file.size/1024).toFixed(0)} KB${state.source==='onedrive'?' · OneDrive':''}`;
      status(`${heroes.length} Helden erkannt. Datei wurde nicht verändert.`,'ok');
      const requested=new URLSearchParams(location.search).get('hero');
      const initial=(requested&&heroes.find(h=>h.name.toLocaleLowerCase('de')===requested.toLocaleLowerCase('de')))||heroes.find(h=>/^Karl Menzel$/i.test(h.name))||heroes.find(h=>/Karl/i.test(h.name))||heroes[0];
      $('#heroSelect').value=initial.key; renderHero(initial);
      $('#workspace').scrollIntoView({behavior:'smooth',block:'start'});
    }catch(err){ console.error(err); status('Fehler: '+(err?.message||err),'error'); }
  }


