  function deriveBasis(props){
    const pm=propMap(props),A=n=>currentAttr(pm,n),p=n=>pm.get(n),extra=n=>{const x=p(n);return x?x.value+x.mod:0;};
    const vals=[];
    if(p('Lebensenergie'))vals.push({name:'LeP',value:Math.ceil((A('Konstitution')*2+A('Körperkraft'))/2)+extra('Lebensenergie'),note:'Maximum'});
    if(p('Ausdauer'))vals.push({name:'AuP',value:Math.ceil((A('Mut')+A('Konstitution')+A('Gewandtheit'))/2)+extra('Ausdauer'),note:'Maximum'});
    if(p('Astralenergie')&&extra('Astralenergie')!==0)vals.push({name:'AsP',value:Math.ceil((A('Mut')+A('Intuition')+A('Charisma'))/2)+extra('Astralenergie'),note:'Maximum'});
    if(p('Karmaenergie')&&extra('Karmaenergie')!==0)vals.push({name:'KaP',value:extra('Karmaenergie'),note:'XML-Wert'});
    if(p('Magieresistenz'))vals.push({name:'MR',value:Math.floor((A('Mut')+A('Klugheit')+A('Konstitution'))/5)+extra('Magieresistenz'),note:'aktuell'});
    [['ini','INI'],['at','AT-Basis'],['pa','PA-Basis'],['fk','FK-Basis']].forEach(([key,label])=>{const x=p(key);if(x)vals.push({name:label,value:x.value+x.mod,note:'aktuell'});});
    const so=p('Sozialstatus');if(so)vals.push({name:'SO',value:so.value+so.mod,note:'Sozialstatus'});
    return vals;
  }

