  // ---- v15 Würfeltisch: erst vorbereiten, dann würfeln -------------------
  const ATTR_FROM_SHORT=Object.fromEntries(primaryNames.map(n=>[short[n],n]));
  const DICE_ANIM_KEY='heldenmobil:ui:dice-animation:v1',TAB_ORDER_KEY='heldenmobil:ui:tab-order:v1';
