  function secureDie(sides){sides=Math.max(2,Math.floor(Number(sides)||6));const a=new Uint32Array(1),space=4294967296,limit=Math.floor(space/sides)*sides;let x;do{crypto.getRandomValues(a);x=a[0];}while(x>=limit);return x%sides+1;}
