  $$('.tab').forEach(btn=>btn.addEventListener('click',()=>{if(btn.disabled||$('.tabs').classList.contains('sort-mode'))return;$$('.tab').forEach(b=>b.classList.toggle('active',b===btn));$$('.section').forEach(s=>s.classList.toggle('active',s.id===btn.dataset.tab));if(btn.dataset.tab==='dashboard')renderDashboard();}));
  document.addEventListener('click',e=>{const el=e.target.closest('[data-roll-ref]');if(!el)return;const req=rollRegistry.get(el.dataset.rollRef);if(req){e.preventDefault();openDice(req);}});document.addEventListener('keydown',e=>{const el=e.target.closest?.('[data-roll-ref]');if(el&&(e.key==='Enter'||e.key===' ')){const req=rollRegistry.get(el.dataset.rollRef);if(req){e.preventDefault();openDice(req);}}});
